def trace(input_data):
    sess = TraceSession(
        algorithm="Stack-Based Reversal",
        input_data=input_data,
        pseudocode=["Push all values onto stack", "Pop each value and place into reversed array", "Return reversed list"]
    )
    values = input_data["values"]
    n = len(values)
    arr = sess.array("original", values)
    stack = sess.stack("stack", [])
    with sess.step("Push phase"):
        for i, val in enumerate(values):
            arr.highlight(i, role="current")
            stack.push(val)
    rev_arr = sess.array("reversed", [0] * n)
    rev_ptr = sess.pointer("rev_idx", on=rev_arr, idx=0)
    with sess.step("Pop phase"):
        while not stack.empty():
            val = stack.pop()
            rev_arr[rev_ptr.idx] = val
            rev_ptr.move(rev_ptr.idx + 1, reason=f"Stored {val}")
    result = rev_arr.to_list()
    sess.result(result)
    trace = sess.to_trace()
    for event in trace["events"]:
        op = event.get("op")
        targets = event.get("targets", [])
        ids = [t.get("id", "") for t in targets]
        reason = event.get("reason", "")
        if op == "create" and "original" in ids:
            event["code_line"] = 2
        elif op == "create" and "stack" in ids:
            event["code_line"] = 2
        elif op == "push":
            event["code_line"] = 4
        elif op == "create" and "reversed" in ids:
            event["code_line"] = 5
        elif op == "create" and "rev_idx" in ids:
            event["code_line"] = 5
        elif op in ("pop", "set", "move"):
            if "rev_idx" in ids or "reversed" in ids:
                event["code_line"] = 7
            else:
                event["code_line"] = 7
        elif event.get("role") == "answer":
            event["code_line"] = 8
        else:
            event["code_line"] = 6
    return trace
